	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}
	productUUID, err := uuid.Parse(productID)
	if err != nil {
		return nil, fmt.Errorf("invalid product ID: %w", err)
	}

	// Determine the user type (User, Vendor, or SideSwapper)
