	if err := r.DB.Where("user_id = ?", userUUID).First(&cart).Error; err != nil {
		if gorm.ErrRecordNotFound == err {
			cart = model.Cart{
				UserID:   userUUID,
				UserType: userType,
			}
			if err := r.DB.Create(&cart).Error; err != nil {
				return nil, err
			}
		} else {
			return nil, err
		}
	}

