func (r *queryResolver) PurchaseHistory(ctx context.Context) ([]*model.PurchaseHistory, error) {
	// Get the user ID from the context
	userIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get user ID: %v", err)
	}

	// Parse UUID
	userUUID, err := uuid.Parse(*userIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}

	// Fetch the user's cart
	var cart model.Cart
	if err := r.DB.Where("user_id = ?", userUUID).Preload("Items.Product").First(&cart).Error; err != nil {
		return nil, fmt.Errorf("cart not found: %w", err)
	}
	// Initialize the purchase history slice
	var purchaseHistories []*model.PurchaseHistory

	// Process each item in the cart to create a PurchaseHistory
	for _, item := range cart.Items {
		// Prepare the PurchaseHistoryItem
		historyItem := &model.PurchaseHistoryItem{
			ID:       item.ID.String(),
			Name:     *item.Product.Name,
			Price:    *item.Product.Price,
			Quantity: fmt.Sprintf("%d", item.Quantity),
			ImageURL: item.Product.ImageUrls[0], // Assuming the first image is used
		}
		trackingNumber := fmt.Sprintf("%d", rand.Intn(1000000)) //random number as a string from 0 to 999999
		id, err := helper.GenerateOrderCartID(cart.ID.String())
		if err != nil {
			return nil, fmt.Errorf("failed to generate order cart ID: %w", err)
		}
		purchaseHistory := &model.PurchaseHistory{
			ID:   id,
			Date: item.UpdatedAt.Format("2006-01-02"),
			// Status:         string(item.DeliveryStatus.Status),
			Items:          []*model.PurchaseHistoryItem{historyItem},
			TrackingNumber: &trackingNumber,
		}

		// Add this PurchaseHistory to the result list
		purchaseHistories = append(purchaseHistories, purchaseHistory)
	}

	return purchaseHistories, nil
}

func (r *queryResolver) GetAllCart(ctx context.Context) ([]*model.VendorOrder, error) {
	// Define a slice to hold the carts
	var carts []*model.Cart
	/*vendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}
	vendorUUID, err := uuid.Parse(*vendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID: %v", err)
	}*/
	// Query all carts from the database and preload the cart items and their associated products and vendors
	if err := r.DB.Preload("Items.Product.Vendor").Find(&carts).Error; err != nil {
		return nil, fmt.Errorf("failed to retrieve carts: %w", err)
	}
	/*if err := r.DB.Preload("Items.Product.Vendor").
	 Joins("JOIN cart_items ON cart_items.cart_id = carts.id").
	 Joins("JOIN products ON products.id = cart_items.product_id").
			Where("products.vendor_id = ?", vendorUUID).
			Find(&carts).Error; err != nil {
			return nil, fmt.Errorf("failed to retrieve carts: %w", err)
		}*/

	// Map to hold user names and numbers by their IDs
	userNames := make(map[string]string)
	userNumbers := make(map[string]string)
	userID := make(map[string]string)

	for _, cart := range carts {
		// Check if the user is a regular user
		var user model.User
		if err := r.DB.Where("id = ?", cart.UserID).First(&user).Error; err == nil {
			userID[cart.UserID.String()] = user.ID.String()
			userNames[cart.UserID.String()] = user.Name
			userNumbers[cart.UserID.String()] = user.Number
			continue
		}

		// Check if the user is a vendor
		var vendor model.Vendor
		if err := r.DB.Where("id = ?", cart.UserID).First(&vendor).Error; err == nil {
			userID[cart.UserID.String()] = vendor.ID.String()

			userNames[cart.UserID.String()] = vendor.Name
			userNumbers[cart.UserID.String()] = vendor.Number
			continue
		}

		// Check if the user is a side swapper
		var sideSwapper model.SideSwapper
		if err := r.DB.Where("id = ?", cart.UserID).First(&sideSwapper).Error; err == nil {
			userID[cart.UserID.String()] = sideSwapper.ID.String()
			userNames[cart.UserID.String()] = sideSwapper.Name
			userNumbers[cart.UserID.String()] = sideSwapper.Number
			continue
		}
	}

	// Map to gather VendorOrders by vendor ID
	vendorOrderMap := make(map[string]*model.VendorOrder)

	// Iterate over the carts and generate vendor orders
	for _, cart := range carts {
		for _, item := range cart.Items {
			// Ensure that the product and vendor exist
			if item.Product != nil && item.Product.Vendor != nil {
				vendorID := item.Product.Vendor.ID.String()

				// Check if the vendor is already in the map
				if _, exists := vendorOrderMap[vendorID]; !exists {
					// Create a new VendorOrder if not exists
					vendorOrderMap[vendorID] = &model.VendorOrder{
						ID:            vendorID,
						Name:          item.Product.Vendor.Name,
						Email:         "vendors@domain.com", // Example static email
						Phone:         item.Product.Vendor.Number,
						Status:        "active", // Example static status
						Orders:        []*model.Order{},
						LastOrderDate: cart.CreatedAt.Format("2006-01-02"),
						TotalOrders:   0,
					}
				}
				_, err := helper.GenerateOrderCartID(cart.ID.String())
				if err != nil {
					return nil, fmt.Errorf("failed to generate order cart ID: %w", err)
				}
				// Create an order for this cart
				_, err = strconv.ParseFloat(*item.Product.Price, 64)
				if err != nil {
					return nil, fmt.Errorf("failed to parse product price: %w", err)
				}
				order := &model.Order{
					// ID:              generatedid,
					// CustomerName:    userNames[cart.UserID.String()],
					// CustomerID:      userID[cart.UserID.String()],
					Date:            cart.CreatedAt.Format("2006-01-02"),
					DeliveryAddress: "123 Example Street", // Example address
					Status:          "pending",            // Example status
					PaymentStatus:   "paid",               // Example payment status
					PaymentMethod:   "Credit Card",        // Example payment method
					ShippingMethod:  "Standard",           // Example shipping method
					// Items: []*model.OrderItem{
					// 	{
					// 		// ID:       item.ID.String(),
					// 		Name:     *item.Product.Name,
					// 		Quantity: item.Quantity,
					// 		Price:    price,
					// 	},
					// },
					EstimatedDeliveryDate: cart.CreatedAt.AddDate(0, 0, 5).Format("2006-01-02"),
				}

				// Append the order to the vendor's orders
				vendorOrderMap[vendorID].Orders = append(vendorOrderMap[vendorID].Orders, order)
				vendorOrderMap[vendorID].TotalOrders++ // Increment total orders for the vendor
			}
		}
	}

	// Convert the vendor order map to a slice
	var vendorOrders []*model.VendorOrder
	for _, vendorOrder := range vendorOrderMap {
		vendorOrders = append(vendorOrders, vendorOrder)
	}

	// Return the populated vendor orders
	return vendorOrders, nil
}

func (r *queryResolver) AllCart(ctx context.Context) ([]*model.Cart, error) {
	var carts []*model.Cart

	// Query all carts from the database and preload the cart items and their associated products and vendors
	if err := r.DB.Preload("Items.Product.Vendor.Product").Find(&carts).Error; err != nil {
		return nil, fmt.Errorf("failed to retrieve carts: %w", err)
	}

	for _, cart := range carts {
		// Check if the user is a regular user
		var user model.User
		if err := r.DB.Where("id = ?", cart.UserID).First(&user).Error; err == nil {
			cart.UserName = user.Name
			cart.UserNumber = user.Number
			continue
		}

		// Check if the user is a vendor
		var vendor model.Vendor
		if err := r.DB.Where("id = ?", cart.UserID).First(&vendor).Error; err == nil {
			cart.UserName = vendor.Name
			cart.UserNumber = vendor.Number
			continue
		}

		// Check if the user is a side swapper
		var sideSwapper model.SideSwapper
		if err := r.DB.Where("id = ?", cart.UserID).First(&sideSwapper).Error; err == nil {
			cart.UserName = sideSwapper.Name
			cart.UserNumber = sideSwapper.Number
			continue
		}
	}

	return carts, nil
}

func (r *queryResolver) GetOrder(ctx context.Context, orderItemsID string) (*model.OrderData, error) {
	// Retrieve the Order based on orderItemsID
	var order model.Order
	if err := r.DB.Where("id = ?", orderItemsID).First(&order).Error; err != nil {
		return nil, fmt.Errorf("failed to find Order with ID %s: %w", orderItemsID, err)
	}

	// Retrieve related Group items for the given orderItemsID
	var orderItems []*model.Group
	if err := r.DB.
		Where("order_items_id = ?", order.ID).
		Preload("CartItem").
		Preload("CartItem.Product").
		Find(&orderItems).Error; err != nil {
		return nil, fmt.Errorf("failed to find Group items with orderItemsID %s: %w", orderItemsID, err)
	}

	// Construct the OrderData response
	orderData := &model.OrderData{
		Infor:      &order,
		OrderItems: orderItems,
	}

	return orderData, nil
}

func (r *queryResolver) GetAllOrder(ctx context.Context) ([]*model.OrderData, error) {
	// Retrieve all orders from the database
	var orders []*model.Order
	if err := r.DB.Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to retrieve orders: %w", err)
	}

	// Initialize a slice to hold the complete order data
	var allOrderData []*model.OrderData

	// Iterate over each order and fetch associated Group items and CartItem details
	for _, order := range orders {
		// Find Group items related to the current order
		var orderItems []*model.Group
		if err := r.DB.
			Where("order_items_id = ?", order.ID).
			Preload("CartItem").
			Preload("CartItem.Product").
			Preload("CartItem.PurchaseMetaData").
			Preload("CartItem.DeliveryStatus").
			Preload("CartItem.DeliveryMetaData").
			Find(&orderItems).Error; err != nil {
			return nil, fmt.Errorf("failed to find Group items for order ID %s: %w", order.ID, err)
		}

		// Append the order and associated items to the OrderData slice
		orderData := &model.OrderData{
			Infor:      order,
			OrderItems: orderItems,
		}
		allOrderData = append(allOrderData, orderData)
	}

	return allOrderData, nil
}

func (r *queryResolver) OrderHistory(ctx context.Context) ([]*model.Order, error) {
	// Get the user ID from the context
	userIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get user ID: %v", err)
	}

	// Parse user ID into UUID format
	userUUID, err := uuid.Parse(*userIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}

	// Fetch all orders for the user
	var orders []*model.Order
	if err := r.DB.Where("customer_id = ?", userUUID).
		Order("created_at DESC").       // Order by most recent
		Preload("OrderItems").          // Load associated items with each order
		Preload("OrderItems.CartItem"). // Load associated items with each order
		Preload("OrderItems.CartItem.Product").
		Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch order history: %w", err)
	}

	return orders, nil
}

func (r *queryResolver) GetVendorID(ctx context.Context, cartItemID string) (string, error) {
	// Parse the cartItemID to a UUID
	cartItemUUID, err := uuid.Parse(cartItemID)
	if err != nil {
		return "", fmt.Errorf("invalid cart item ID: %v", err)
	}

	// Create a variable to hold the cart item
	var cartItem model.CartItem

	// Fetch the cart item from the database
	if err := r.DB.Where("id = ?", cartItemUUID).Preload("Product").Find(&cartItem).Error; err != nil {
		return "", fmt.Errorf("failed to find cart item: %v", err)
	}

	// Check if the product exists
	if cartItem.Product == nil {
		return "", fmt.Errorf("no product associated with this cart item")
	}

	// Retrieve the vendor ID from the product
	vendorID := cartItem.Product.VendorID.String()

	// Return the vendor ID
	return vendorID, nil
}

